query viewOrderQuery(
  $id: ID!
) {
  node(id: $id){
    ... on Order {
        id
        _id
        total
        subtotal
        discount_value
      items {
        __typename
        ... on VariantSnapshot {
          product_uid: product_id
          id
          _id
          groupID
          image {
            path(version: version2)
            id
          }
          customer_files {
            name
            files {
              path
              key
            }
          }
          title
          price
          variant_id
          fulfillment_status
          carrier
          tracking_number
          tracking_link
          refund_id
          payment_id
          removed_at
          sku
          custom_options {
            name
            key
            files {
              url
            }
            value
            type
          }
          payment {
            id
            source {
              payment_gateway {
                active
                type
                id
              }
              id
            }
          }
          options {
            option_id: id
            label
            value
          }
        }
        ... on OrderBumpSnapshot {
          product_uid: product_id
          groupID
          id
          _id
          sku
          image {
            path(version: version2)
            id
          }
          title
          price
          fulfillment_status
          carrier
          tracking_number
          tracking_link
          refund_id
          payment_id
          removed_at
          payment {
            id
            source {
              payment_gateway {
                active
                type
                id
              }
              id
            }
          }
        }
        ... on Node {
          __isNode: __typename
          id
        }
      }
    }
  }  
}

